const app=document.querySelector('#app');
const modal=document.querySelector('#modal');
const cloud=window.seva;
const photo=(id,w=1200)=>id.startsWith('http')?id:`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const samples=[{id:'as-101',title:'A little room to breathe',area:'Wanowrie',beds:2,rent:24000,size:1050,furnish:'Semi-furnished',image:'photo-1600607687920-4e2a09cf159d'},{id:'as-102',title:'Light-filled family living',area:'Fatima Nagar',beds:3,rent:32000,size:1420,furnish:'Furnished',image:'photo-1600210492486-724fe5c67fb0'},{id:'as-103',title:'Your quiet corner of Pune',area:'Wanwadi',beds:2,rent:22000,size:980,furnish:'Unfurnished',image:'photo-1600566753086-00f18fb6b3ea'}];
let saved=JSON.parse(localStorage.getItem('as-saved')||'[]');
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'₹'+Number(v||0).toLocaleString('en-IN');
function toast(message){const el=document.querySelector('#toast');if(!el)return;el.textContent=message;el.style.display='block';setTimeout(()=>el.style.display='none',3500)}
function header(){const user=cloud?.user;return `<header><a class="brand" href="#home"><span class="mark">⌂</span><span>SevaDera<small>HOMES FOR THOSE WHO SERVE</small></span></a><nav><a href="#homes">Find a home</a><a href="#services">Move-in services</a><a href="#owner">${user?'My listings':'List your home ↗'}</a><a href="#account">${user?'My account':'Sign in'}</a>${cloud?.staff?'<a class="button" href="#admin">Admin review</a>':''}</nav><button class="mobile-menu" aria-label="Open navigation" onclick="document.querySelector('nav').classList.toggle('open')">☰</button></header>`}
function footer(){return `<footer><a class="brand" href="#home"><span class="mark">⌂</span>SevaDera</a><p>Rooted in Wanwadi. Built around your next chapter.<br>Independent housing portal · Free during launch</p><a href="#account">My account ↗</a></footer>`}
function card(h,live=false){const img=live&&h.property_photos?.[0]?cloud.publicPhotoUrl(h.property_photos[0].storage_path):photo(h.image);const id=live?`share/${h.public_slug}`:`property/${h.id}`;return `<article class="property"><div class="property-image"><a href="#${id}"><img src="${img}" alt="${escapeHtml(h.title)}" loading="lazy"></a><button class="save" aria-label="Save ${escapeHtml(h.title)}" onclick="toggleSave('${h.id}')">${saved.includes(h.id)?'♥':'♡'}</button>${!live?'<span class="image-label">Sample home</span>':''}</div><div class="property-title"><a href="#${id}"><h3>${escapeHtml(h.title)}</h3></a><strong>${money(h.rent)}<span class="muted"> / mo</span></strong></div><div class="meta">${escapeHtml(h.area)}, Pune · ${h.bedrooms||h.beds} bedrooms · ${h.size_sqft||h.size||'—'} sq ft</div><div class="card-bottom"><span>${escapeHtml(h.furnishing||h.furnish||'')}</span><button class="text-button" onclick="shareHome('${live?h.public_slug:h.id}',${live})">Share ↗</button></div></article>`}
function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];localStorage.setItem('as-saved',JSON.stringify(saved));render()}
function services(){return `<div class="services">${[['⌂','Home viewings','Get a closer look before you make the journey. Request a local viewing.'],['▦','Packers & movers','Plan your move, from the first box to the final delivery.'],['✧','A fresh start','Arrange cleaning and small fixes before you collect your keys.'],['⌁','Everyday essentials','Get help organising internet, utilities and your first days at home.'],['▤','Mess & tiffin','Home-style meals for duty days, families and late arrivals. Request a trusted local mess or tiffin plan.']].map(([i,t,d])=>`<article><div class="service-icon">${i}</div><h3>${t}</h3><p>${d}</p><button class="text-button" onclick="requestService('${t}')">Request help ↗</button></article>`).join('')}</div>`}
function homePage(){return `<div class="hero">${header()}<div class="hero-content"><div><div class="eyebrow">For those who serve. For those who stand beside them.</div><h1>Home, wherever<br>duty takes you.</h1></div><div class="hero-aside">A home for your family.<br>A little peace of mind for you.<br>Find your space and settle in, starting in Wanwadi.<br><a href="#homes" class="button light">Find your home <span>↗</span></a></div></div><div class="hero-foot"><span>Wanwadi & neighbouring communities, Pune</span><span>Private introductions · ₹0 platform fee at launch</span></div></div><section class="section intro"><div class="eyebrow">Built around the service community</div><div><h2>You look after the nation.<br>Find a place to call your own.</h2><p>From a new posting to a new beginning. SevaDera brings private homes and move-in support together for Army families, military doctors, CRPF personnel and public servants.</p><div class="audience">${['Army & service families','Army doctors','CRPF & CAPF','Government & CBI','Veterans & Army brats'].map(x=>`<span class="pill">${x}</span>`).join('')}</div></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">A quieter place to come home to</div><h2>Homes for your next posting.</h2></div><a class="button outline" href="#homes">View all homes ↗</a></div><div class="cards">${samples.map(h=>card(h)).join('')}</div><p class="muted">Illustrative homes show the experience before launch. Reviewed owner listings appear here after admin approval.</p></section><section class="section"><div class="section-head"><div><div class="eyebrow">More than finding a home</div><h2>From moving to settling in.</h2></div><a href="#services">Explore services ↗</a></div>${services()}</section><div class="cta"><div><h2>Open your door to<br>a family that serves.</h2><p>Clear costs. Private contact details. A considered introduction.</p></div><a class="button lime" href="#owner">List your home for free ↗</a></div>${footer()}`}
function browse(){return `${header()}<div class="page-title"><div class="eyebrow">Your next chapter, in Pune</div><h1 style="font-size:52px">Find a place that feels right.</h1><p>Browse the launch preview or share an approved owner listing.</p></div><section class="section"><div class="cards">${samples.map(h=>card(h)).join('')}</div></section>${footer()}`}
function authPage(){return `${header()}<section class="section"><div class="eyebrow">Private access</div><h2>Sign in to your SevaDera space.</h2><div class="dashboard"><form class="form panel" id="auth-form"><label>Email<input type="email" name="email" required autocomplete="email"></label><label>Password<input type="password" name="password" required minlength="8" autocomplete="current-password"></label><label class="signup-only">Your name<input name="display_name" maxlength="80"></label><label class="signup-only">I am a<select name="seller_category"><option>Army personnel</option><option>Army doctor</option><option>CRPF / CAPF</option><option>Government / CBI</option><option>Veteran / Army brat</option><option>Other</option></select></label><button class="button" id="auth-submit">Sign in ↗</button><button type="button" class="text-button" id="auth-toggle">Create a seller account</button><p class="muted">Your phone, exact address and identity details stay private.</p></form></div></section>${footer()}`}
function ownerPage(){if(!cloud?.user)return `${header()}<section class="section"><div class="notice">Sign in to create and manage a listing.</div><a class="button" href="#account">Sign in ↗</a></section>${footer()}`;return `${header()}<section class="section"><div class="eyebrow">Seller dashboard</div><h2>List your home for trusted families.</h2><p>Submit a property for admin review. Exact address and direct contact stay private.</p><div class="dashboard"><div><div id="my-listings" class="panel"><p>Loading your listings…</p></div></div><form class="form panel" id="listing-form"><input type="hidden" name="id"><label>Seller category<select name="seller_category"><option>Army personnel</option><option>Army doctor</option><option>CRPF / CAPF</option><option>Government / CBI</option><option>Veteran / Army brat</option><option>Other</option></select></label><label>Property title<input name="title" required maxlength="100" placeholder="A bright family home in Wanwadi"></label><label>Neighbourhood<select name="area"><option>Wanwadi</option><option>Wanowrie</option><option>Fatima Nagar</option><option>Salunke Vihar</option></select></label><div class="form-grid"><label>Monthly rent<input name="rent" type="number" min="1" required></label><label>Bedrooms<select name="bedrooms"><option>1</option><option>2</option><option>3</option><option>4</option></select></label><label>Size (sq ft)<input name="size_sqft" type="number" min="1"></label><label>Furnishing<select name="furnishing"><option>Unfurnished</option><option>Semi-furnished</option><option>Furnished</option></select></label></div><label>Exact address<input name="exact_address" required maxlength="500"></label><label>Private contact phone<input name="contact_phone" required maxlength="25"></label><label>Property description<textarea name="description" maxlength="3000"></textarea></label><label>Property photos<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><button class="button">Save draft and upload photos ↗</button><p class="muted">Photos are re-encoded to remove location metadata before upload.</p></form></div></section>${footer()}`}
async function loadListings(){const el=document.querySelector('#my-listings');if(!el)return;try{const rows=await cloud.listings.mine();el.innerHTML=`<h3>Your listings</h3>${rows.map(x=>`<div class="listing-row"><span><strong>${escapeHtml(x.title)}</strong><br><small>${escapeHtml(x.area)} · ${money(x.rent)} · ${escapeHtml(x.status)}</small></span>${x.status==='draft'?`<button class="button" onclick="submitListing('${x.id}')">Submit for review</button>`:x.status==='published'?`<button class="button outline" onclick="shareHome('${x.public_slug}',true)">Share on WhatsApp</button>`:''}</div>`).join('')||'<p class="muted">Your first listing starts here.</p>'}` }catch(e){el.innerHTML=`<div class="notice">${escapeHtml(e.message)}</div>`}}
async function submitListing(id){try{await cloud.listings.submit(id);toast('Listing sent for admin review.');loadListings()}catch(e){toast(e.message)}}
async function adminPage(){if(!cloud?.staff)return `${header()}<section class="section"><div class="notice">Admin access is restricted.</div></section>${footer()}`;let rows=[];try{rows=await cloud.listings.pending()}catch(e){return `${header()}<section class="section"><div class="notice">${escapeHtml(e.message)}</div></section>${footer()}`}return `${header()}<section class="section"><div class="eyebrow">Admin review</div><h2>Review trusted homes.</h2><div class="panel">${rows.map(x=>`<article class="listing-row"><div><h3>${escapeHtml(x.title)}</h3><p>${escapeHtml(x.area)} · ${money(x.rent)} · ${x.bedrooms} bedrooms</p><p class="muted">${escapeHtml(x.property_private?.[0]?.exact_address||'Private address')}</p>${(x.property_photos||[]).map(ph=>`<img class="admin-thumb" src="${cloud.publicPhotoUrl(ph.storage_path)}" alt="Listing photo">`).join('')}</div><div class="actions"><button class="button" onclick="moderate('${x.id}','approve')">Approve</button><button class="button outline" onclick="moderate('${x.id}','reject')">Reject</button></div></article>`).join('')||'<p>No pending listings.</p>'}</div></section>${footer()}`}
async function moderate(id,action){try{if(action==='approve')await cloud.listings.approve(id);else{const reason=prompt('Reason for rejection?')||'Please update the listing.';await cloud.listings.reject(id,reason)}toast('Review updated.');render()}catch(e){toast(e.message)}}
async function shareHome(slug,live=false){const url=new URL(location.href);url.hash=live?`share/${slug}`:`property/${slug}`;const wa=`https://wa.me/?text=${encodeURIComponent(`SevaDera home: ${url.href}`)}`;showModal(`<div class="eyebrow">Share this home</div><h2>Ready for WhatsApp.</h2><p>The public link shows photos and public facts only. Private seller details stay protected.</p><input class="share-input" aria-label="Share link" readonly value="${escapeHtml(url.href)}"><div class="actions"><a class="button" href="${wa}" target="_blank" rel="noopener">Share on WhatsApp ↗</a><button class="button outline" id="copy-share">Copy link</button></div>`);document.querySelector('#copy-share').onclick=async()=>{await navigator.clipboard?.writeText(url.href);toast('Share link copied')}}
function showModal(content){document.querySelector('#modal-body').innerHTML=content;modal.showModal()}
function requestService(service){showModal(`<h2>${escapeHtml(service)}</h2><p>Tell us what you need and the SevaDera team will follow up.</p><form class="form" id="request"><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Preferred date<input name="date" type="date" required></label><label>Notes<textarea name="notes"></textarea></label><button class="button">Send request</button></form>`);document.querySelector('#request').onsubmit=e=>{e.preventDefault();modal.close();toast('Request saved. We will follow up shortly.')}}
function propertyPage(id){const h=samples.find(x=>x.id===id);return `${header()}<section class="section"><div class="eyebrow">Sample home · ${h?.area||'Pune'}</div><h2>${escapeHtml(h?.title||'Home unavailable')}</h2>${h?`<img class="modal-photo" src="${photo(h.image,2000)}" alt="${escapeHtml(h.title)}"><p>${money(h.rent)} / month · ${h.beds} bedrooms · ${h.furnish}</p><button class="button" onclick="shareHome('${h.id}')">Share photos ↗</button>`:''}</section>${footer()}`}
async function sharedPage(slug){try{const h=await cloud.listings.publicBySlug(slug);if(!h)return `${header()}<section class="section"><h2>Listing unavailable</h2></section>${footer()}`;const photos=(h.photos||[]).sort((a,b)=>a.position-b.position);return `<div class="share-gallery"><div class="share-gallery-head"><span class="brand"><span class="mark">⌂</span>SevaDera</span><span>Reviewed home · ${escapeHtml(h.area)}, Pune</span></div><img src="${cloud.publicPhotoUrl(photos[0]?.path||'')}" alt="${escapeHtml(h.title)}"><section class="section"><div class="eyebrow">A trusted local listing</div><h1>${escapeHtml(h.title)}</h1><p>${money(h.rent)} / month · ${h.bedrooms} bedrooms · ${escapeHtml(h.furnishing)}</p><p>${escapeHtml(h.description||'A considered home for your next posting.')}</p><div class="actions"><a class="button" href="https://wa.me/?text=${encodeURIComponent(`SevaDera home: ${h.title} · ${h.area}, Pune · ${money(h.rent)} / month · ${location.href}`)}" target="_blank" rel="noopener">Share on WhatsApp ↗</a><a class="button outline" href="#home">Browse SevaDera</a></div></section></div>`}catch(e){return `${header()}<section class="section"><div class="notice">${escapeHtml(e.message)}</div></section>${footer()}`}}
function account(){if(!cloud?.user)return authPage();return `${header()}<section class="section"><div class="eyebrow">Everything in one place</div><h2>Your SevaDera account.</h2><div class="notice">Signed in as ${escapeHtml(cloud.user.email)}</div><div class="actions"><a class="button" href="#owner">My listings ↗</a>${cloud.staff?'<a class="button outline" href="#admin">Admin review ↗</a>':''}<button class="button outline" onclick="cloud.auth.signOut().then(()=>render())">Sign out</button></div></section>${footer()}`}
function render(){const route=location.hash.slice(1).split('?')[0]||'home';if(modal.open)modal.close();if(route.startsWith('share/')){app.innerHTML='<div class="empty">Loading shared home…</div>';sharedPage(route.slice(6)).then(html=>app.innerHTML=html);return}let html=route==='home'?homePage():route==='homes'?browse():route==='owner'?ownerPage():route==='account'?account():route==='admin'?'<div class="empty">Loading admin review…</div>':route.startsWith('property/')?propertyPage(route.slice(9)):route==='services'?`${header()}<section class="section"><h2>Move-in services.</h2>${services()}</section>${footer()}`:`${header()}<section class="section"><h2>Page unavailable</h2></section>${footer()}`;app.innerHTML=html;if(route==='owner'&&cloud?.user)loadListings();if(route==='admin')adminPage().then(x=>app.innerHTML=x)}
document.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});window.addEventListener('seva-session',render);
document.addEventListener('submit',async e=>{if(e.target.id==='auth-form'){e.preventDefault();const f=new FormData(e.target);try{if(document.body.dataset.signup==='1')await cloud.auth.signUp(f.get('email'),f.get('password'),f.get('display_name'),f.get('seller_category'));else await cloud.auth.signIn(f.get('email'),f.get('password'));toast('Welcome to SevaDera.');location.hash='account'}catch(err){toast(err.message)}}if(e.target.id==='listing-form'){e.preventDefault();if(!cloud.user)return toast('Sign in first.');const f=new FormData(e.target);try{const id=await cloud.listings.save({title:f.get('title'),area:f.get('area'),bedrooms:Number(f.get('bedrooms')),rent:Number(f.get('rent')),deposit:0,maintenance:0,brokerage:0,furnishing:f.get('furnishing'),description:f.get('description'),size_sqft:Number(f.get('size_sqft')||0)},{exact_address:f.get('exact_address'),contact_phone:f.get('contact_phone')},f.get('id')||undefined);const files=[...(f.getAll('photos')||[])].filter(x=>x?.size);for(let i=0;i<files.length;i++)await cloud.photoUpload(id,files[i],i);toast('Draft saved. Submit it from My listings.');e.target.reset();loadListings()}catch(err){toast(err.message)}}});
document.addEventListener('click',e=>{if(e.target.id==='auth-toggle'){document.body.dataset.signup=document.body.dataset.signup==='1'?'0':'1';document.querySelectorAll('.signup-only').forEach(x=>x.style.display=document.body.dataset.signup==='1'?'block':'none');document.querySelector('#auth-submit').textContent=document.body.dataset.signup==='1'?'Create account ↗':'Sign in ↗';e.target.textContent=document.body.dataset.signup==='1'?'Already have an account? Sign in':'Create a seller account'}});
render();
